def _semantic_page_key(entity: dict[str, Any]) -> tuple[str, str, str]:
    kind = "file" if entity.get("kind") == "file" else str(entity.get("kind_original") or entity.get("kind"))
    return (str(entity.get("path")), kind, str(entity.get("qualified_name") or entity.get("name")))

def relink_preserved_notes(output: Path, graph: dict[str, Any], projection: dict[str, Any]) -> dict[str, Any]:
    """Retarget preserved Wiki links after deterministic human titles change."""
    output = output.resolve()
    plan_path = output / "migration" / "plan.json"
    if not plan_path.is_file():
        return {"schema_version": MIGRATION_SCHEMA_VERSION, "status": "not-applicable", "changed_files": []}
    plan = json_load(plan_path)
    origin = Path(plan["origin"]["output"])
    old_graph_path = origin / "graph.json"
    old_projection_path = origin / "markdown" / "projection.json"
    if not old_graph_path.is_file() or not old_projection_path.is_file():
        raise CkbError(f"migration note relink requires the origin graph and Markdown projection: {origin}")
    old_graph = json_load(old_graph_path)
    old_projection = json_load(old_projection_path)
    old_entities = {entity["id"]: entity for entity in old_graph.get("entities", [])}
    new_by_key = {_semantic_page_key(entity): entity for entity in graph.get("entities", [])}
    new_title_by_id = {page["id"]: page["title"] for page in projection.get("pages", [])}
    title_map: dict[str, str] = {}
    for page in old_projection.get("pages", []):
        old_entity = old_entities.get(page.get("id"))
        if not old_entity:
            continue
        new_entity = new_by_key.get(_semantic_page_key(old_entity))
        new_title = new_title_by_id.get(new_entity.get("id")) if new_entity else None
        old_title = page.get("title")
        if old_title and new_title and old_title != new_title:
            title_map[str(old_title)] = str(new_title)

    def replace_links(text: str) -> str:
        result = text
        for old_title, new_title in sorted(title_map.items(), key=lambda item: (-len(item[0]), item[0])):
            result = result.replace(f"[[{old_title}]]", f"[[{new_title}]]")
            result = result.replace(f"[[{old_title}|", f"[[{new_title}|")
        return result

    changed: list[str] = []
    for item in plan.get("mutable_files", []):
        target = _mutable_target(output, str(item["relative_target"]))
        if not target.is_file():
            continue
        if target.suffix.casefold() == ".md":
            text = target.read_text(encoding="utf-8")
            updated = replace_links(text)
            if updated != text:
                target.write_text(updated, encoding="utf-8", newline="\n")
                changed.append(item["relative_target"])
        elif target.suffix.casefold() == ".json" and "workspace-meta" in target.parts:
            try:
                value = json_load(target)
            except (json.JSONDecodeError, OSError):
                continue
            updated = False
            linked = value.get("linked_pages")
            if isinstance(linked, list):
                replacement = [title_map.get(str(page), str(page)) for page in linked]
                if replacement != linked:
                    value["linked_pages"] = replacement
                    updated = True
            for field, root_name in (("file", "human"), ("compatibility_file", "markdown")):
                current = value.get(field)
                if isinstance(current, str):
                    candidate = output / root_name / Path(current.replace("\\", "/")).name
                    kind = str(value.get("kind") or "session")
                    directory = {"change": "changes", "analysis": "analysis", "pitfall": "pitfalls", "experiment": "experiments", "session": "sessions"}.get(kind, "user")
                    candidate = output / root_name / directory / candidate.name
                    rendered = str(candidate.resolve())
                    if rendered != current:
                        value[field] = rendered
                        updated = True
            if isinstance(value.get("compatibility_file"), str):
                uri = "obsidian://open?path=" + quote(value["compatibility_file"], safe="")
                if value.get("obsidian_uri") != uri:
                    value["obsidian_uri"] = uri
                    updated = True
            if updated:
                json_write(target, value)
                changed.append(item["relative_target"])
        item["post_migration_sha256"] = sha256_file(target)
        item["post_migration_size"] = target.stat().st_size
    plan["note_relink"] = {
        "status": "passed",
        "title_map": title_map,
        "changed_files": sorted(set(changed)),
        "updated_at_utc": utc_now(),
    }
    json_write(plan_path, plan)
    result = {
        "schema_version": MIGRATION_SCHEMA_VERSION,
        "status": "passed",
        "title_map_count": len(title_map),
        "changed_files": sorted(set(changed)),
        "title_map": title_map,
    }
    json_write(output / "migration" / "note-relink.json", result)
    return result

def replace_links(text: str) -> str:
        result = text
        for old_title, new_title in sorted(title_map.items(), key=lambda item: (-len(item[0]), item[0])):
            result = result.replace(f"[[{old_title}]]", f"[[{new_title}]]")
            result = result.replace(f"[[{old_title}|", f"[[{new_title}|")
        return result

def migration_status(output: Path) -> dict[str, Any]:
    output = output.resolve()
    state = json_load(output / "state.json")
    migration = state.get("migration")
    if not migration:
        raise CkbError(f"output is not an incremental migration: {output}")
    pending = [pack for pack in state.get("review_packs", []) if pack.get("status") != "passed"]
    audit = audit_migration(output, require_complete_reviews=False)
    if state.get("status") == "complete" and audit.get("status") == "passed":
        status = "complete"
    else:
        status = "pending-agent-review" if pending else "ready-to-finalize"
    return {
        "schema_version": MIGRATION_SCHEMA_VERSION,
        "status": status,
        "migration": migration,
        "pending_review_packs": [pack["id"] for pack in pending],
        "next_review_template": pending[0].get("review_template_path") if pending else None,
        "audit": audit,
    }

def estimated_tokens(text: str | bytes, divisor: int = TOKEN_BYTES_DIVISOR) -> int:
    data = text if isinstance(text, bytes) else text.encode("utf-8")
    return ceil(len(data) / divisor)

def _test_path(path: str) -> bool:
    parts = PurePosixPath(path).parts
    stem = PurePosixPath(path).stem.lower()
    return any(part.lower() in {"test", "tests"} for part in parts) or stem.startswith("test_") or stem.endswith(("_test", ".test", "-test"))

def _eligible(entity: dict[str, Any], entry_ids: set[str]) -> bool:
    if entity.get("kind") not in HUMAN_CODE_UNIT_KINDS:
        return False
    if entity["id"] in entry_ids:
        return True
    return bool(entity.get("page_eligible"))

def build_navigation_plan(
    entities: list[dict[str, Any]],
    links: list[dict[str, Any]],
    entry_ids: list[str],
    page_config: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Assign page/appendix/boundary using fixed evidence and configured quotas."""
    config = page_config or DEFAULT_PAGE_CONFIG
    page_limits = config["page_limits"]
    ordinary_file_limit = int(page_limits["ordinary_file"])
    core_file_limit = int(page_limits["core_file"])
    adjacent_file_limit = int(page_limits["adjacent_file"])
    core_entry_limit = int(page_limits["core_per_entry"])
    adjacent_entry_limit = int(page_limits["adjacent_per_entry"])
    facts = _graph_facts(entities, links)
    by_id: dict[str, dict[str, Any]] = facts["by_id"]
    entries = {value for value in entry_ids if value in by_id}
    entry_owners = {ancestor for entry in entries for ancestor in _ancestors(entry, by_id) if by_id[ancestor]["kind"] != "file"}
    entry_direct: set[str] = set()
    for entry in entries:
        entry_direct.update(facts["outgoing"].get(entry, set()))
        entry_direct.update(facts["incoming"].get(entry, set()))
    selected_pages: set[str] = {entity["id"] for entity in entities if entity["kind"] == "file"}
    boundary_ids = {entity["id"] for entity in entities if entity["kind"] == "boundary"}
    selected_pages.update(boundary_ids)
    candidates_by_path: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for entity in entities:
        if _eligible(entity, entries):
            candidates_by_path[entity["path"]].append(entity)
    rank_kwargs = {"entry_ids": entries, "entry_owners": entry_owners, "entry_direct": entry_direct, "facts": facts}
    for values in candidates_by_path.values():
        values.sort(key=lambda value: _rank(value, **rank_kwargs))

    clusters: list[dict[str, Any]] = []
    core_paths: set[str] = set()
    neighbor_ids_all: set[str] = set()
    adjacent_paths: set[str] = set()
    selected_key_count_by_path: dict[str, int] = defaultdict(int)
    for entry_id in sorted(entries):
        entry = by_id[entry_id]
        if not _eligible(entry, entries):
            clusters.append({"entry_id": entry_id, "core_page_ids": [], "neighbor_page_ids": [], "landing_page_id": next((value for value in _ancestors(entry_id, by_id) if by_id[value]["kind"] == "file"), None)})
            continue
        same_path = candidates_by_path.get(entry["path"], [])
        core_pool: list[dict[str, Any]] = [entry] if _eligible(entry, entries) else []
        for ancestor_id in _ancestors(entry_id, by_id):
            ancestor = by_id[ancestor_id]
            if ancestor["kind"] != "file" and _eligible(ancestor, entries):
                core_pool.append(ancestor)
        direct_same = [by_id[value] for value in facts["outgoing"].get(entry_id, set()) | facts["incoming"].get(entry_id, set()) if value in by_id and by_id[value]["path"] == entry["path"] and _eligible(by_id[value], entries)]
        core_pool.extend(sorted(direct_same, key=lambda value: _rank(value, **rank_kwargs)))
        entry_parent = entry.get("parent_id")
        core_pool.extend(value for value in same_path if value.get("parent_id") == entry_parent)
        core_ids: list[str] = []
        for value in core_pool:
            if len(core_ids) >= core_entry_limit:
                break
            if value["id"] in core_ids:
                continue
            if value["id"] in selected_pages:
                core_ids.append(value["id"])
                continue
            if selected_key_count_by_path[value["path"]] >= core_file_limit:
                continue
            core_ids.append(value["id"])
            selected_pages.add(value["id"])
            selected_key_count_by_path[value["path"]] += 1
        core_paths.update(by_id[value]["path"] for value in core_ids)

        neighbor_pool: list[dict[str, Any]] = []
        for core_id in core_ids:
            for neighbor_id in facts["outgoing"].get(core_id, set()) | facts["incoming"].get(core_id, set()):
                neighbor = by_id.get(neighbor_id)
                if neighbor and neighbor["path"] != entry["path"] and _eligible(neighbor, entries):
                    neighbor_pool.append(neighbor)
        neighbor_pool.sort(key=lambda value: _rank(value, **rank_kwargs))
        neighbor_ids: list[str] = []
        for value in neighbor_pool:
            if len(neighbor_ids) >= adjacent_entry_limit:
                break
            if value["id"] in neighbor_ids or value["id"] in selected_pages:
                continue
            if value["path"] in core_paths or selected_key_count_by_path[value["path"]] >= adjacent_file_limit:
                continue
            neighbor_ids.append(value["id"])
            selected_pages.add(value["id"])
            selected_key_count_by_path[value["path"]] += 1
        neighbor_ids_all.update(neighbor_ids)
        adjacent_paths.update(by_id[value]["path"] for value in neighbor_ids)
        adjacent_paths.difference_update(core_paths)
        clusters.append({"entry_id": entry_id, "core_page_ids": core_ids, "neighbor_page_ids": neighbor_ids})

    # Every non-core source file receives no more than its configured ordinary
    # or adjacent quota.  Ranking and tie breaks remain entirely deterministic.
    for path, values in sorted(candidates_by_path.items()):
        if path in core_paths:
            continue
        limit = adjacent_file_limit if path in adjacent_paths else ordinary_file_limit
        for value in values:
            if selected_key_count_by_path[path] >= limit:
                break
            if value["id"] not in selected_pages:
                selected_pages.add(value["id"])
                selected_key_count_by_path[path] += 1

    owner_by_entity: dict[str, str] = {}
    decisions: list[dict[str, Any]] = []
    file_page_by_path = {entity["path"]: entity["id"] for entity in entities if entity["kind"] == "file"}
    for entity in entities:
        entity_id = entity["id"]
        if entity_id in boundary_ids:
            classification = "boundary"
            owner = entity_id
        elif entity_id in selected_pages:
            classification = "page"
            owner = entity_id
        else:
            classification = "appendix"
            owner = next((ancestor for ancestor in _ancestors(entity_id, by_id) if ancestor in selected_pages and by_id[ancestor]["kind"] != "file"), file_page_by_path.get(entity["path"]))
            if not owner:
                raise AuditError(f"appendix entity has no deterministic owner: {entity_id}")
        owner_by_entity[entity_id] = owner
        evidence = []
        if entity_id in entries:
            evidence.append("explicit-entry")
        if entity_id in entry_owners:
            evidence.append("entry-lexical-owner")
        if entity_id in entry_direct:
            evidence.append("entry-direct-relation")
        if facts["cross_degree"].get(entity_id, 0):
            evidence.append("cross-file-reference")
        if entity.get("is_public_or_exported"):
            evidence.append("public-or-exported")
        if entity.get("hard_exclusion"):
            evidence.append(f"hard-exclusion:{entity['hard_exclusion']}")
        decisions.append(
            {
                "entity_id": entity_id,
                "classification": classification,
                "owner_page_id": owner,
                "rank_evidence": evidence or ["fixed-order-default"],
                "cross_file_degree": facts["cross_degree"].get(entity_id, 0),
                "total_degree": facts["total_degree"].get(entity_id, 0),
            }
        )

    page_count_by_path: dict[str, int] = defaultdict(int)
    for entity_id in selected_pages - boundary_ids:
        entity = by_id[entity_id]
        if entity["kind"] != "file":
            page_count_by_path[entity["path"]] += 1
    quota_errors = []
    for path, count in sorted(page_count_by_path.items()):
        limit = core_file_limit if path in core_paths else (adjacent_file_limit if path in adjacent_paths else ordinary_file_limit)
        if count > limit:
            quota_errors.append({"path": path, "count": count, "limit": limit})
    for cluster in clusters:
        if len(cluster["core_page_ids"]) > core_entry_limit or len(cluster["neighbor_page_ids"]) > adjacent_entry_limit:
            quota_errors.append(
                {
                    "entry_id": cluster["entry_id"],
                    "reason": "entry-cluster-quota",
                    "core_count": len(cluster["core_page_ids"]),
                    "core_limit": core_entry_limit,
                    "adjacent_count": len(cluster["neighbor_page_ids"]),
                    "adjacent_limit": adjacent_entry_limit,
                }
            )
    return {
        "schema_version": 3,
        "algorithm": "human-code-unit-navigation-v3-configured",
        "page_limits": dict(page_limits),
        "classifications": sorted(PAGE_CLASSIFICATIONS),
        "decisions": decisions,
        "entity_owner_pages": owner_by_entity,
        "page_entity_ids": sorted(selected_pages - boundary_ids),
        "boundary_entity_ids": sorted(boundary_ids),
        "entry_clusters": clusters,
        "core_paths": sorted(core_paths),
        "adjacent_paths": sorted(adjacent_paths),
        "page_count_by_path": dict(sorted(page_count_by_path.items())),
        "quota_errors": quota_errors,
        "status": "passed" if not quota_errors else "failed",
    }

def write_generated_ownership(root: Path, generated: list[Path]) -> dict[str, Any]:
    files = sorted(path.relative_to(root).as_posix() for path in generated if path.is_file())
    record = {"schema_version": 1, "status": "ready", "files": files}
    json_write(root / ".ckb-generated-files.json", record)
    return record

def audit_obsidian(root: Path) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    required = (
        ".obsidian/app.json",
        ".obsidian/core-plugins.json",
        ".obsidian/appearance.json",
        ".obsidian/snippets/ckb.css",
        ".ckb-generated-files.json",
        "INDEX.md",
        "WIKI.md",
    )
    for relative in required:
        if not (root / relative).is_file():
            errors.append({"reason": "obsidian-vault-file-missing", "path": relative})
    for name in NOTE_DIRECTORIES:
        if not (root / name).is_dir():
            errors.append({"reason": "obsidian-note-directory-missing", "path": name})
    ownership = root / ".ckb-generated-files.json"
    if ownership.is_file() and ".obsidian/workspace.json" in json_load(ownership).get("files", []):
        errors.append({"reason": "machine-specific-obsidian-workspace-owned-by-generator"})
    try:
        plugins = json_load(root / ".obsidian/core-plugins.json")
        for plugin in ("backlink", "outgoing-link", "tag-pane", "graph", "global-search"):
            if plugin not in plugins:
                errors.append({"reason": "obsidian-core-plugin-missing", "plugin": plugin})
    except (OSError, json.JSONDecodeError, CkbError) as exc:
        errors.append({"reason": "obsidian-config-invalid", "detail": str(exc)})
    css_path = root / ".obsidian/snippets/ckb.css"
    if css_path.is_file():
        css = css_path.read_text(encoding="utf-8")
        if "body .inline-title { display: none; }" not in css:
            errors.append({"reason": "obsidian-inline-title-not-hidden"})
    return errors

def _merge_known(default: Any, supplied: Any, path: str) -> Any:
    if isinstance(default, dict):
        if not isinstance(supplied, dict):
            raise CkbError(f"page config {path or '<root>'} must be an object")
        unknown = sorted(set(supplied) - set(default))
        if unknown:
            raise CkbError(f"page config has unknown keys at {path or '<root>'}: {unknown}")
        return {
            key: _merge_known(value, supplied[key], f"{path}.{key}".strip(".")) if key in supplied else copy.deepcopy(value)
            for key, value in default.items()
        }
    return copy.deepcopy(supplied)

def _integer(value: Any, path: str, minimum: int, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
        raise CkbError(f"page config {path} must be an integer in [{minimum}, {maximum}]")
    return value

def _section_list(config: dict[str, Any], name: str) -> None:
    value = config["content"][name]
    if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
        raise CkbError(f"page config content.{name} must be a string array")
    if len(value) != len(set(value)):
        raise CkbError(f"page config content.{name} contains duplicate sections")
    unknown = sorted(set(value) - _SECTION_SETS[name])
    if unknown:
        raise CkbError(f"page config content.{name} has unknown sections: {unknown}")
    missing = sorted(_REQUIRED_SECTIONS[name] - set(value))
    if missing:
        raise CkbError(
            f"page config content.{name} omits audited required sections: {missing}"
        )

def normalize_page_config(value: dict[str, Any]) -> dict[str, Any]:
    """Merge a partial user JSON with defaults and enforce the audit contract."""
    if not isinstance(value, dict):
        raise CkbError("page config root must be a JSON object")
    if value.get("schema_version") != PAGE_CONFIG_SCHEMA_VERSION:
        raise CkbError(
            f"page config schema_version must be {PAGE_CONFIG_SCHEMA_VERSION}"
        )
    config = _merge_known(DEFAULT_PAGE_CONFIG, value, "")

    limits = config["page_limits"]
    for key in ("ordinary_file", "core_file", "adjacent_file"):
        limits[key] = _integer(limits[key], f"page_limits.{key}", 0, 32)
    for key in ("core_per_entry", "adjacent_per_entry"):
        limits[key] = _integer(limits[key], f"page_limits.{key}", 0, 64)

    for name in _SECTION_SETS:
        _section_list(config, name)
    fields = config["content"]["overview_fields"]
    if (
        not isinstance(fields, list)
        or not fields
        or len(fields) != len(set(fields))
        or any(value not in {"meaning", "role"} for value in fields)
    ):
        raise CkbError(
            "page config content.overview_fields must contain one or both of: meaning, role"
        )
    if config["content"]["appendix_mode"] not in {"collapsed", "expanded"}:
        raise CkbError("page config content.appendix_mode must be collapsed or expanded")
    headings = config["content"]["headings"]
    for key, heading in headings.items():
        if not isinstance(heading, str) or not heading.strip() or len(heading) > 64 or "\n" in heading or "\r" in heading:
            raise CkbError(f"page config content.headings.{key} must be one non-empty line of at most 64 characters")
        headings[key] = heading.strip()

    relation_limits = config["relation_limits"]
    for key in ("direct", "aggregate", "test", "boundary"):
        relation_limits[key] = _integer(relation_limits[key], f"relation_limits.{key}", 0, 200)

    context = config["context"]
    context["module_max_tokens"] = _integer(context["module_max_tokens"], "context.module_max_tokens", 1_000, 1_000_000)
    context["task_max_tokens"] = _integer(context["task_max_tokens"], "context.task_max_tokens", 500, 1_000_000)
    context["total_max_tokens"] = _integer(context["total_max_tokens"], "context.total_max_tokens", 1_000, 2_000_000)
    context["reserved_agent_tokens"] = _integer(context["reserved_agent_tokens"], "context.reserved_agent_tokens", 0, 1_000_000)
    context["bytes_per_token"] = _integer(context["bytes_per_token"], "context.bytes_per_token", 1, 16)
    if context["task_max_tokens"] > context["module_max_tokens"]:
        raise CkbError("page config context.task_max_tokens must not exceed module_max_tokens")
    if context["module_max_tokens"] + context["reserved_agent_tokens"] > context["total_max_tokens"]:
        raise CkbError(
            "page config context.module_max_tokens plus reserved_agent_tokens must not exceed total_max_tokens"
        )

    review = config["review_packs"]
    for kind in ("page", "appendix"):
        review[kind]["max_files"] = _integer(review[kind]["max_files"], f"review_packs.{kind}.max_files", 1, 200)
        review[kind]["max_items"] = _integer(review[kind]["max_items"], f"review_packs.{kind}.max_items", 1, 5_000)
        review[kind]["max_tokens"] = _integer(review[kind]["max_tokens"], f"review_packs.{kind}.max_tokens", 500, 1_000_000)
        if review[kind]["max_tokens"] > context["total_max_tokens"] - context["reserved_agent_tokens"]:
            raise CkbError(
                f"page config review_packs.{kind}.max_tokens exceeds the non-Agent context budget"
            )
    return config

def page_config_bytes(config: dict[str, Any]) -> bytes:
    normalized = normalize_page_config(config)
    return (json.dumps(normalized, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
